mapper.select:
select *
from message_record
where id = #{id, jdbcType=BIGINT}

mapper.update:
UPDATE message_record SET
status = #{status},
send_time = #{sendTime}
WHERE id = #{id, jdbcType=BIGINT}

UPDATE message_record SET
success_count = #{successCount},
fail_count = #{failCount}
WHERE id = #{id, jdbcType=BIGINT}

UPDATE message_record SET
retry_count = retry_count + 1
WHERE id = #{id}

mapper.insert:
INSERT INTO doc.message_receiver_detail
(record_id, receiver, read_status, read_time, create_time)
VALUES(#{recordId}, #{receiver}, 1, NOW(), NOW());
